import itertools, random

def build_clauses(nvars):
    clauses=[]
    for combo in itertools.combinations(range(nvars),3):
        for signs in itertools.product([1,-1],repeat=3):
            clauses.append(tuple(zip(combo,signs)))
    return clauses

def lit_val(lit, assign):
    v,s=lit
    return assign[v] if s==1 else (not assign[v])

def sat_clause(cl, assign):
    vals=[lit_val(l,assign) for l in cl]
    return not (vals[0]==vals[1]==vals[2])

def exists_aux(clset, lvals, naux):
    # aux vars indices 3..3+naux-1
    for aux in itertools.product([False,True],repeat=naux):
        assign=list(lvals)+list(aux)
        if all(sat_clause(c,assign) for c in clset):
            return True
    return False

def check(clset, naux):
    for lv in itertools.product([False,True],repeat=3):
        exp = any(lv)
        if exists_aux(clset,lv,naux)!=exp:
            return False
    return True

random.seed(1)
for naux in [2,3]:
    clauses=build_clauses(3+naux)
    # clauses must involve at least one aux var? not necessarily but likely
    found=None
    for trial in range(2000000):
        k=random.randint(3,6)
        clset=tuple(random.sample(clauses,k))
        if check(clset,naux):
            found=clset; break
    print("naux",naux,"found",found)
    if found: break
